// Parse AI Agent output into structured JSON for the frontend
const output = $input.first().json.output;

let results = [];
try {
  const jsonMatch = output.match(/\[[\s\S]*\]/);
  if (jsonMatch) {
    results = JSON.parse(jsonMatch[0]);
  } else {
    results = [{ "Category": "Service Improvement Analysis", "Details": output }];
  }
} catch (e) {
  results = [{ "Category": "Service Improvement Analysis", "Details": output }];
}

return [{ json: { success: true, agent: "Help Improve Service", results: results } }];
